1	Motion graphics 187
2	{"id": "graphics-graphic-clips", "name": "Graphic clips", "summary": "A graphic clip is a motion graphic drawn fresh on every frame by a small JavaScript module kept inside your project, not a video or image file.", "page": "graphics/what-is-a-graphic", "anchor": "graphic-clips", "where": "Insert ▸ Graphic…"}
3	{"id": "graphics-modules", "name": "Modules", "summary": "A module is one file, graphics/<name>.js, in the project's package that draws an SVG picture for any frame you ask for.", "page": "graphics/what-is-a-graphic", "anchor": "modules", "where": "Project package ▸ graphics/ folder"}
4	{"id": "graphics-clips-share-a-module", "name": "Clips sharing one module", "summary": "Many clips can be drawn by one module, each with its own property values, size and timeline.", "page": "graphics/what-is-a-graphic", "anchor": "clips-sharing-one-module", "where": "Timeline"}
5	{"id": "graphics-typed-properties", "name": "Typed properties", "summary": "A module declares typed properties, and a value you don't set draws with the module's own default.", "page": "graphics/what-is-a-graphic", "anchor": "properties", "where": "Clip tab ▸ Graphic ▸ Properties"}
6	{"id": "graphics-same-frame-same-pixels", "name": "Same frame, same pixels", "summary": "A graphic is deterministic: the same frame with the same properties always draws the same pixels, in the preview and in an export.", "page": "graphics/what-is-a-graphic", "anchor": "same-frame-same-pixels"}
7	{"id": "graphics-module-names", "name": "Module names", "summary": "A module's name is its file stem: lowercase letters, digits and -, starting with a letter or a digit, at most 63 characters.", "page": "graphics/what-is-a-graphic", "anchor": "module-names"}
8	{"id": "graphics-gradients-dont-band", "name": "Gradients don't band", "summary": "Where a gradient is rounded to the 256 levels a graphic is drawn in, Frame Job adds a fixed, fine pattern under half a level, so a dark gradient shades smoothly instead of in steps.", "page": "graphics/what-is-a-graphic", "anchor": "gradients-dont-band", "where": "Automatic"}
9	{"id": "graphics-folder", "name": "The graphics folder", "summary": "Each project keeps its graphics in a graphics/ folder inside the .framejob package, holding modules, fonts/, assets/ and history/.", "page": "graphics/what-is-a-graphic", "anchor": "the-graphics-folder", "where": "Clip tab ▸ Graphic ▸ Source ▸ Reveal in Finder"}
10	{"id": "graphics-in-untitled-projects", "name": "Graphics in an untitled project", "summary": "An unsaved project can use graphics: they are kept in a temporary folder and move into the package when you first save it.", "page": "graphics/what-is-a-graphic", "anchor": "graphics-in-an-untitled-project"}
11	{"id": "graphics-templates-are-copied", "name": "Templates are copied into the project", "summary": "Inserting a template writes your own editable copy into graphics/ under a free name, so each insert can be edited on its own.", "page": "graphics/what-is-a-graphic", "anchor": "templates-are-copied-in", "where": "Insert ▸ Graphic…"}
12	{"id": "graphics-only-timeline", "name": "A graphics-only timeline", "summary": "A timeline of nothing but graphics, text, shapes and images still plays and exports.", "page": "graphics/what-is-a-graphic", "anchor": "a-graphics-only-timeline"}
13	{"id": "graphics-in-hdr-projects", "name": "Graphics in HDR projects", "summary": "In an HDR (HLG) project, graphics are drawn at HDR reference white (203 cd/m²), like titles and shapes, so a white graphic matches SDR white rather than reaching into the highlights.", "page": "graphics/what-is-a-graphic", "anchor": "graphics-in-hdr-projects"}
14	{"id": "graphics-limits", "name": "Graphics limits", "summary": "The fixed limits on graphics, gathered in one place.", "page": "graphics/what-is-a-graphic", "anchor": "limits"}
15	{"id": "graphics-insert-sheet", "name": "The Insert Graphic sheet", "summary": "Insert ▸ Graphic… opens a browser for choosing a bundled template or a project graphic, with categories, a list and a looping preview.", "page": "graphics/insert-a-graphic", "anchor": "the-insert-graphic-sheet", "where": "Insert ▸ Graphic… (no key equivalent)"}
16	{"id": "graphics-browser-categories", "name": "Categories", "summary": "The left list files graphics by category, with This Project first when the project's graphics/ folder holds a module.", "page": "graphics/insert-a-graphic", "anchor": "categories", "where": "Insert ▸ Graphic… ▸ categories list"}
17	{"id": "graphics-browser-list", "name": "The graphics list", "summary": "The middle list shows the chosen category's graphics by title.", "page": "graphics/insert-a-graphic", "anchor": "the-graphics-list", "where": "Insert ▸ Graphic… ▸ graphics list"}
18	{"id": "graphics-browser-preview", "name": "The looping preview", "summary": "The chosen graphic plays on a loop over a checkerboard, at the project's canvas shape, with its title and one-line description under it.", "page": "graphics/insert-a-graphic", "anchor": "the-looping-preview", "where": "Insert ▸ Graphic… ▸ preview"}
19	{"id": "graphics-insert", "name": "Insert", "summary": "Insert, Return or a double-click on a graphic places the chosen graphic at the playhead, selects the new clip and closes the sheet.", "page": "graphics/insert-a-graphic", "anchor": "insert-a-graphic", "where": "Insert ▸ Graphic… ▸ Insert", "keys": "Return"}
20	{"id": "graphics-browser-cancel", "name": "Cancel", "summary": "Cancel or Esc closes the sheet without changing anything.", "page": "graphics/insert-a-graphic", "anchor": "insert-a-graphic", "where": "Insert ▸ Graphic… ▸ Cancel", "keys": "Esc"}
21	{"id": "graphics-insert-from-this-project", "name": "Insert from This Project", "summary": "Inserting from This Project places another clip drawn by that module as it is, the same way, and copies nothing.", "page": "graphics/insert-a-graphic", "anchor": "insert-from-this-project", "where": "Insert ▸ Graphic… ▸ This Project"}
22	{"id": "graphics-from-file", "name": "From File…", "summary": "From File… closes the sheet and asks for a .js module to copy into the project and place, or a .fjgraphic to import.", "page": "graphics/insert-a-graphic", "anchor": "insert-from-a-file", "where": "Insert ▸ Graphic… ▸ From File…"}
23	{"id": "graphics-from-file-naming", "name": "How From File… names a module", "summary": "From File… names the module after the chosen file, made into a legal, free module name.", "page": "graphics/insert-a-graphic", "anchor": "how-the-module-is-named", "where": "Insert ▸ Graphic… ▸ From File…"}
24	{"id": "graphics-where-it-lands", "name": "Where an inserted graphic lands", "summary": "An inserted graphic goes at the playhead on the front track if it fits there, otherwise on a new track above everything.", "page": "graphics/insert-a-graphic", "anchor": "where-it-lands", "where": "Insert ▸ Graphic…"}
25	{"id": "graphics-default-length-and-size", "name": "Default length and size", "summary": "A new clip's length and size come from the module's own meta when it gives them; otherwise it is 5 seconds long and the canvas's size.", "page": "graphics/insert-a-graphic", "anchor": "default-length-and-size", "where": "Insert ▸ Graphic…"}
26	{"id": "graphics-compile-refusal", "name": "A module that doesn't compile", "summary": "If the module doesn't compile, no clip is placed and you are told its first error and line.", "page": "graphics/insert-a-graphic", "anchor": "a-module-that-doesnt-compile", "where": "Insert ▸ Graphic…"}
27	{"id": "graphics-clip-on-the-timeline", "name": "A graphic clip on the timeline", "summary": "On the timeline a graphic clip is labelled Graphic, with a {} glyph, and has no filmstrip.", "page": "graphics/insert-a-graphic", "anchor": "on-the-timeline", "where": "Timeline"}
28	{"id": "graphics-bundled-templates", "name": "The 23 bundled templates", "summary": "Frame Job ships 23 ready-made graphics in four categories, drawn by code and fully editable once inserted.", "page": "graphics/templates", "anchor": "the-bundled-templates", "where": "Insert ▸ Graphic…"}
29	{"id": "graphics-templates-any-canvas", "name": "Templates at any canvas shape", "summary": "The seventeen newer templates stay inside the title-safe area at every frame in landscape, portrait and square, and long text is fitted or wrapped.", "page": "graphics/templates", "anchor": "any-canvas-shape", "where": "Insert ▸ Graphic…"}
30	{"id": "graphics-templates-end-clean", "name": "Templates end clean", "summary": "The seventeen newer templates each have an accent colour and an outro in about their last 15 frames, leaving the last frame bare.", "page": "graphics/templates", "anchor": "templates-end-clean"}
31	{"id": "graphics-template-fonts-and-glyphs", "name": "Template fonts and glyphs", "summary": "Templates use bundled fonts and generic vector glyphs only, never a brand's artwork.", "page": "graphics/templates", "anchor": "template-fonts-and-glyphs"}
32	{"id": "graphics-template-arrow-highlight", "name": "Arrow highlight", "summary": "A rounded box drawn on around a spot, an arrow growing toward it from the side nearer the frame's centre, and a label at the arrow's tail.", "page": "graphics/templates", "anchor": "arrow-highlight", "where": "Insert ▸ Graphic… ▸ Screencast ▸ Arrow highlight"}
33	{"id": "graphics-template-bar-chart", "name": "Bar chart", "summary": "A titled bar chart whose bars grow in turn, from comma-separated values and labels.", "page": "graphics/templates", "anchor": "bar-chart", "where": "Insert ▸ Graphic… ▸ Data & Time ▸ Bar chart"}
34	{"id": "graphics-template-callout", "name": "Callout", "summary": "A circle that draws itself on, with an arrow and a label, at a position on the frame.", "page": "graphics/templates", "anchor": "callout", "where": "Insert ▸ Graphic… ▸ Screencast ▸ Callout"}
35	{"id": "graphics-template-chapter-card", "name": "Chapter card", "summary": "A full-frame card with a large outlined chapter number, a kicker, an accent rule drawing across and the title rising into view.", "page": "graphics/templates", "anchor": "chapter-card", "where": "Insert ▸ Graphic… ▸ Titles & Text ▸ Chapter card"}
36	{"id": "graphics-template-countdown", "name": "Countdown", "summary": "A timer counting down or up one step a second inside a ring that empties or fills, pulsing on each tick and flashing at the end.", "page": "graphics/templates", "anchor": "countdown", "where": "Insert ▸ Graphic… ▸ Data & Time ▸ Countdown"}
37	{"id": "graphics-template-counter", "name": "Counter", "summary": "A number counting from one value to another with thousands separators, a prefix and a label.", "page": "graphics/templates", "anchor": "counter", "where": "Insert ▸ Graphic… ▸ Data & Time ▸ Counter"}
38	{"id": "graphics-template-donut-chart", "name": "Donut chart", "summary": "A titled donut whose slices sweep in turn, the first slice's share counting up in the centre, with a legend beside it (below it in portrait).", "page": "graphics/templates", "anchor": "donut-chart", "where": "Insert ▸ Graphic… ▸ Data & Time ▸ Donut chart"}
39	{"id": "graphics-template-end-screen", "name": "End screen", "summary": "A full-frame card with a title, two 16:9 placeholders for linked videos side by side, and a subscribe circle centred under them (a column in portrait).", "page": "graphics/templates", "anchor": "end-screen", "where": "Insert ▸ Graphic… ▸ Social & YouTube ▸ End screen"}
40	{"id": "graphics-template-gauge", "name": "Gauge", "summary": "A dial with ticks whose accent arc and needle swing to a value, with the value counting up and its units and label.", "page": "graphics/templates", "anchor": "gauge", "where": "Insert ▸ Graphic… ▸ Data & Time ▸ Gauge"}
41	{"id": "graphics-template-handle-tag", "name": "Handle tag", "summary": "An accent tile holding a generic glyph and a pill with your @handle, at a corner.", "page": "graphics/templates", "anchor": "handle-tag", "where": "Insert ▸ Graphic… ▸ Social & YouTube ▸ Handle tag"}
42	{"id": "graphics-template-keyboard-keys", "name": "Keyboard keys", "summary": "A shortcut such as cmd+shift+4 as keycaps popping in, each pressed in turn, with ⌘ ⇧ ⌥ ⌃ and the arrows drawn as symbols, and a label under them.", "page": "graphics/templates", "anchor": "keyboard-keys", "where": "Insert ▸ Graphic… ▸ Screencast ▸ Keyboard keys"}
43	{"id": "graphics-template-kinetic-type", "name": "Kinetic type", "summary": "A sentence shown word by word, each word springing in, with an accent colour.", "page": "graphics/templates", "anchor": "kinetic-type", "where": "Insert ▸ Graphic… ▸ Titles & Text ▸ Kinetic type"}
44	{"id": "graphics-template-line-chart", "name": "Line chart", "summary": "A titled line drawn on through comma-separated values, a dot popping at each point, an optional area fill and the last value called out.", "page": "graphics/templates", "anchor": "line-chart", "where": "Insert ▸ Graphic… ▸ Data & Time ▸ Line chart"}
45	{"id": "graphics-template-logo-reveal", "name": "Logo reveal", "summary": "A full-frame card on which an accent bar sweeps across, revealing your logo image or a text mark, then becomes a rule over a tagline.", "page": "graphics/templates", "anchor": "logo-reveal", "where": "Insert ▸ Graphic… ▸ Titles & Text ▸ Logo reveal"}
46	{"id": "graphics-template-lower-third", "name": "Lower third", "summary": "A name and subtitle that slide in and fade out, boxed or not, aligned left, centre or right.", "page": "graphics/templates", "anchor": "lower-third", "where": "Insert ▸ Graphic… ▸ Titles & Text ▸ Lower third"}
47	{"id": "graphics-template-news-ticker", "name": "News ticker", "summary": "A band along the foot of the frame with a headline box and items, separated by |, crawling right to left.", "page": "graphics/templates", "anchor": "news-ticker", "where": "Insert ▸ Graphic… ▸ Titles & Text ▸ News ticker"}
48	{"id": "graphics-template-progress-bar", "name": "Progress bar", "summary": "A labelled bar on a plate whose fill grows to a percentage, the figure counting, with a shine across it, at the bottom, centre or top.", "page": "graphics/templates", "anchor": "progress-bar", "where": "Insert ▸ Graphic… ▸ Data & Time ▸ Progress bar"}
49	{"id": "graphics-template-quote-card", "name": "Quote card", "summary": "A full-frame card with a large quote mark, the quote's lines fading up in turn, and the attribution sliding in.", "page": "graphics/templates", "anchor": "quote-card", "where": "Insert ▸ Graphic… ▸ Titles & Text ▸ Quote card"}
50	{"id": "graphics-template-social-popup", "name": "Social popup", "summary": "A notification card at a corner with a generic avatar and a handle (and, for a comment, its text), its heart, speech bubble or share arrow popping as the count ticks up by one.", "page": "graphics/templates", "anchor": "social-popup", "where": "Insert ▸ Graphic… ▸ Social & YouTube ▸ Social popup"}
51	{"id": "graphics-template-step-badge", "name": "Step badge", "summary": "A numbered accent circle popping in at a corner, with a label panel wiping out from behind it.", "page": "graphics/templates", "anchor": "step-badge", "where": "Insert ▸ Graphic… ▸ Screencast ▸ Step badge"}
52	{"id": "graphics-template-subscribe-button", "name": "Subscribe button", "summary": "A subscribe button a cursor clicks: it turns to its done label with a check, and a bell pops in beside it and rings after a second click.", "page": "graphics/templates", "anchor": "subscribe-button", "where": "Insert ▸ Graphic… ▸ Social & YouTube ▸ Subscribe button"}
53	{"id": "graphics-template-title-card", "name": "Title card", "summary": "A title fitted to the frame and a kicker over a two-colour gradient, fading in and out.", "page": "graphics/templates", "anchor": "title-card", "where": "Insert ▸ Graphic… ▸ Titles & Text ▸ Title card"}
54	{"id": "graphics-template-window-frame", "name": "Window frame", "summary": "A browser or app window's frame (title bar, three dots, a title or address field, an outline) to put over a screen recording on the track below, its inside left clear.", "page": "graphics/templates", "anchor": "window-frame", "where": "Insert ▸ Graphic… ▸ Screencast ▸ Window frame"}
55	{"id": "graphics-export-package", "name": "Export a graphic", "summary": "Export… saves the chosen graphic as a .fjgraphic file (Finder calls it a Frame Job Graphic) holding its module and only the project fonts and pictures it uses.", "page": "graphics/share-a-graphic", "anchor": "export-a-graphic", "where": "Insert ▸ Graphic… ▸ Export…"}
56	{"id": "graphics-package-what-it-packs", "name": "What a package finds to pack", "summary": "To find which fonts and pictures belong in the package, Frame Job draws the graphic and packs exactly those it saw used.", "page": "graphics/share-a-graphic", "anchor": "what-a-package-packs", "where": "Insert ▸ Graphic… ▸ Export…"}
57	{"id": "graphics-package-format", "name": "The .fjgraphic file", "summary": "A graphic package is a stored zip of manifest.json, the module, fonts/ and assets/, and two exports of one graphic are byte-identical.", "page": "graphics/share-a-graphic", "anchor": "the-fjgraphic-file"}
58	{"id": "graphics-open-package-from-finder", "name": "Open a .fjgraphic from the Finder", "summary": "Double-click a .fjgraphic, open it with Open With, drop it on Frame Job's Dock icon or open it from a browser's downloads to import it into the front project.", "page": "graphics/share-a-graphic", "anchor": "open-from-the-finder", "where": "Finder: open a .fjgraphic"}
59	{"id": "graphics-import-from-file", "name": "Import with From File…", "summary": "Choosing a .fjgraphic with the Insert Graphic sheet's From File… puts up the Import Graphic sheet for that sheet's own project.", "page": "graphics/share-a-graphic", "anchor": "import-with-from-file", "where": "Insert ▸ Graphic… ▸ From File…"}
60	{"id": "graphics-import-sheet", "name": "The Import Graphic sheet", "summary": "Before anything is copied, a sheet shows the graphic's title and description, the module's name, and its fonts and pictures, and what will happen to each.", "page": "graphics/share-a-graphic", "anchor": "the-import-graphic-sheet", "where": "Import Graphic sheet ▸ Import, Cancel"}
61	{"id": "graphics-after-import", "name": "After an import", "summary": "Import copies the files into graphics/ and opens the Insert Graphic sheet on This Project with the graphic chosen, ready to insert.", "page": "graphics/share-a-graphic", "anchor": "after-an-import", "where": "Import Graphic sheet ▸ Import"}
62	{"id": "graphics-import-name-clashes", "name": "Name clashes on import", "summary": "An import never replaces a file: identical files are reused, a clashing module or font is copied under a new name, and a clashing picture stops the import.", "page": "graphics/share-a-graphic", "anchor": "name-clashes", "where": "Import Graphic sheet"}
63	{"id": "graphics-package-checks", "name": "Package checks", "summary": "A package is checked before anything is copied, and a package that is damaged, compressed, changed after it was written, or written by a newer Frame Job is refused with a sentence saying why.", "page": "graphics/share-a-graphic", "anchor": "package-checks", "where": "Import Graphic sheet"}
64	{"id": "graphics-sub-tab", "name": "The Graphic sub-tab", "summary": "Selected graphic clips show a Graphic sub-tab in the Clip tab, with Source, Properties, Size and Timeline sections.", "page": "graphics/graphic-tab", "anchor": "the-graphic-sub-tab", "where": "Inspector ▸ Clip ▸ Graphic"}
65	{"id": "graphics-picture-sub-tab", "name": "The Picture sub-tab on a graphic", "summary": "A graphic clip has the Picture sub-tab's Transform, Shadow, Filters, Reflection, Spotlight and Obscure, as for any layer, so it can be moved, scaled and faded.", "page": "graphics/graphic-tab", "anchor": "the-picture-sub-tab", "where": "Clip tab ▸ Picture"}
66	{"id": "graphics-clip-sub-tab", "name": "The Clip sub-tab on a graphic", "summary": "A graphic has the clip's timing and Motion in the Clip sub-tab, but no Speed section.", "page": "graphics/graphic-tab", "anchor": "the-clip-sub-tab", "where": "Clip tab ▸ Clip"}
67	{"id": "graphics-source-readouts", "name": "Name, File and Revision", "summary": "The Source section shows what draws the clip: its Name, File and Revision.", "page": "graphics/graphic-tab", "anchor": "name-file-and-revision", "where": "Clip tab ▸ Graphic ▸ Source"}
68	{"id": "graphics-open-in-editor", "name": "Open in Editor", "summary": "Open in Editor opens the module in the app your Mac uses for .js files; save there and the preview redraws within a moment.", "page": "graphics/graphic-tab", "anchor": "open-in-editor", "where": "Clip tab ▸ Graphic ▸ Source ▸ Open in Editor"}
69	{"id": "graphics-reveal-in-finder", "name": "Reveal in Finder", "summary": "Reveal in Finder shows the module's file.", "page": "graphics/graphic-tab", "anchor": "reveal-in-finder", "where": "Clip tab ▸ Graphic ▸ Source ▸ Reveal in Finder"}
70	{"id": "graphics-missing-module", "name": "A missing module", "summary": "When the module file is gone, Source says so and its buttons are disabled.", "page": "graphics/graphic-tab", "anchor": "a-missing-module", "where": "Clip tab ▸ Graphic ▸ Source"}
71	{"id": "graphics-diagnostics-in-source", "name": "Diagnostics in Source", "summary": "Under the buttons, Source lists what the module says about the clip: compile errors and warnings, then what drawing its first frame reported.", "page": "graphics/graphic-tab", "anchor": "diagnostics", "where": "Clip tab ▸ Graphic ▸ Source"}
72	{"id": "graphics-open-a-diagnostic", "name": "Open a diagnostic", "summary": "Click a diagnostic, or its Open button, to open the module in your editor.", "page": "graphics/graphic-tab", "anchor": "open-a-diagnostic", "where": "Clip tab ▸ Graphic ▸ Source ▸ a diagnostic row, or its Open button"}
73	{"id": "graphics-folder-warnings", "name": "In the graphics folder", "summary": "Source lists what the folder scan skipped or could not watch under In the graphics folder, each with a Reveal button.", "page": "graphics/graphic-tab", "anchor": "in-the-graphics-folder", "where": "Clip tab ▸ Graphic ▸ Source ▸ In the graphics folder ▸ Reveal"}
74	{"id": "graphics-several-modules-selected", "name": "Several modules selected", "summary": "When the selected clips are drawn by different modules, Source names them and asks you to select one module's clips to edit its properties.", "page": "graphics/graphic-tab", "anchor": "several-modules-selected", "where": "Clip tab ▸ Graphic ▸ Source"}
75	{"id": "graphics-switch-clips-module", "name": "Switch clips to another module", "summary": "The inspector can't point clips at a different existing module: delete the clips and insert that module again, or have an agent call set_graphic.", "page": "graphics/graphic-tab", "anchor": "switching-clips-to-another-module", "where": "Clip tab ▸ Graphic ▸ Source ▸ Duplicate as New Graphic… (a new copy only)"}
76	{"id": "graphics-property-rows", "name": "Property rows", "summary": "One row appears per property the module declares, in the module's own order, with the module's label and its help text as the tooltip.", "page": "graphics/properties", "anchor": "property-rows", "where": "Clip tab ▸ Graphic ▸ Properties"}
77	{"id": "graphics-property-number", "name": "Number properties", "summary": "A number property is a value field, with a slider when the module gives both a minimum and a maximum.", "page": "graphics/properties", "anchor": "number", "where": "Clip tab ▸ Graphic ▸ Properties"}
78	{"id": "graphics-property-string", "name": "Text properties", "summary": "A string property is a one-line field the width of the inspector, or a text area when the module marks it multiline: true.", "page": "graphics/properties", "anchor": "string", "where": "Clip tab ▸ Graphic ▸ Properties", "keys": "Return"}
79	{"id": "graphics-property-boolean", "name": "Boolean properties", "summary": "A boolean property is a checkbox.", "page": "graphics/properties", "anchor": "boolean", "where": "Clip tab ▸ Graphic ▸ Properties"}
80	{"id": "graphics-property-enum", "name": "Enum properties", "summary": "An enum property is a pop-up of the module's options.", "page": "graphics/properties", "anchor": "enum", "where": "Clip tab ▸ Graphic ▸ Properties"}
81	{"id": "graphics-property-color", "name": "Colour properties", "summary": "A colour property is a colour well.", "page": "graphics/properties", "anchor": "color", "where": "Clip tab ▸ Graphic ▸ Properties"}
82	{"id": "graphics-property-asset", "name": "Asset properties", "summary": "An asset property is a pop-up of None, then every picture in the project's graphics assets, then any picture name that is referred to but missing from the folder.", "page": "graphics/properties", "anchor": "asset", "where": "Clip tab ▸ Graphic ▸ Properties"}
83	{"id": "graphics-properties-reset", "name": "Reset", "summary": "The section's reset clears every stored value so the module draws its own defaults.", "page": "graphics/properties", "anchor": "reset", "where": "Clip tab ▸ Graphic ▸ Properties ▸ section Reset"}
84	{"id": "graphics-default-not-stored", "name": "A value at the default is not stored", "summary": "With no action selected, setting a value back to the module's default clears it, so the clip follows the module's default if it changes later.", "page": "graphics/properties", "anchor": "values-at-the-default", "where": "Clip tab ▸ Graphic ▸ Properties"}
85	{"id": "graphics-edit-several-clips", "name": "Edit several clips of one module", "summary": "With several clips of one module selected, a change to a property row applies to all of them.", "page": "graphics/properties", "anchor": "editing-several-clips", "where": "Clip tab ▸ Graphic ▸ Properties"}
86	{"id": "graphics-stale-properties", "name": "Stale and orphaned values", "summary": "A value the clip holds for a property the module no longer declares stays, dimmed, below the rows, with ⌫ to remove it.", "page": "graphics/properties", "anchor": "leftover-values", "where": "Clip tab ▸ Graphic ▸ Properties ▸ ⌫"}
87	{"id": "graphics-width-and-height", "name": "Width and Height", "summary": "Width and Height set the module's drawing surface, the ctx.width and ctx.height it sees, so text and shapes stay sharp at any size.", "page": "graphics/size-and-timing", "anchor": "width-and-height", "where": "Clip tab ▸ Graphic ▸ Size ▸ Width, Height"}
88	{"id": "graphics-fit-to-canvas", "name": "Fit to Canvas", "summary": "Fit to Canvas sets the size to the canvas's and centres the clip at scale 1.", "page": "graphics/size-and-timing", "anchor": "fit-to-canvas", "where": "Clip tab ▸ Graphic ▸ Size ▸ Fit to Canvas"}
89	{"id": "graphics-own-timeline", "name": "The graphic's own timeline", "summary": "A graphic has a timeline of its own, counted from its first frame, shown in the Timeline section.", "page": "graphics/size-and-timing", "anchor": "the-graphics-own-timeline", "where": "Clip tab ▸ Graphic ▸ Timeline"}
90	{"id": "graphics-timeline-in", "name": "In", "summary": "In shows the graphic frame the clip's first frame shows, and is read only.", "page": "graphics/size-and-timing", "anchor": "the-graphics-own-timeline", "where": "Clip tab ▸ Graphic ▸ Timeline ▸ In"}
91	{"id": "graphics-timeline-length", "name": "Length", "summary": "Length is how long the graphic's own timeline runs, and typing a value pins it, so the animation keeps its pace when the clip's length changes.", "page": "graphics/size-and-timing", "anchor": "length", "where": "Clip tab ▸ Graphic ▸ Timeline ▸ Length"}
92	{"id": "graphics-timeline-follow-clip", "name": "Follow Clip", "summary": "With Follow Clip on, the default, the graphic's timeline ends when the clip ends, so lengthening the clip moves its outro to the new end.", "page": "graphics/size-and-timing", "anchor": "follow-clip", "where": "Clip tab ▸ Graphic ▸ Timeline ▸ Follow Clip"}
93	{"id": "graphics-length-shorter-than-clip", "name": "Length pinned shorter than the clip", "summary": "When Length is pinned shorter than the clip, frames keep counting past it but the module's progress stays at its end.", "page": "graphics/size-and-timing", "anchor": "length-shorter-or-longer-than-the-clip", "where": "Clip tab ▸ Graphic ▸ Timeline"}
94	{"id": "graphics-trim-like-footage", "name": "Trim a graphic like footage", "summary": "Trimming the front of a graphic clip cuts into its animation, and trimming the end never changes a pinned Length.", "page": "graphics/size-and-timing", "anchor": "trim-a-graphic-like-footage", "where": "Timeline: drag a clip edge"}
95	{"id": "graphics-transition-handles", "name": "Graphics and transition handles", "summary": "Adding a transition's head to a graphic clip moves its timeline back to match.", "page": "graphics/size-and-timing", "anchor": "good-to-know", "where": "Timeline: add a transition"}
96	{"id": "graphics-frame-rate-change", "name": "A frame-rate change", "summary": "Changing the project's frame rate moves a graphic's own timeline onto the new frame grid.", "page": "graphics/size-and-timing", "anchor": "good-to-know", "where": "Inspector ▸ Document ▸ Frame Rate"}
97	{"id": "graphics-vertical-resized", "name": "Canvas-sized graphics are re-sized", "summary": "Make Vertical Version re-sizes a graphic exactly the old canvas's size to the new canvas, so the module lays itself out again on the tall frame.", "page": "graphics/vertical-graphics", "anchor": "canvas-sized-graphics", "where": "File ▸ Make Vertical Version…"}
98	{"id": "graphics-vertical-short-side", "name": "Templates measured by the short side", "summary": "The bundled Lower third, Title card, Callout, Bar chart, Counter and Kinetic type templates measure themselves by the canvas's short side, so they fit a tall frame.", "page": "graphics/vertical-graphics", "anchor": "templates-measured-by-the-short-side", "where": "Insert ▸ Graphic…"}
99	{"id": "graphics-vertical-older-copies", "name": "Older template copies are updated", "summary": "Older copies of those six templates in the project are recognised and, in the copy Make a copy opens, rewritten with the current template.", "page": "graphics/vertical-graphics", "anchor": "older-template-copies", "where": "File ▸ Make Vertical Version… ▸ Make a copy"}
100	{"id": "graphics-vertical-own-modules", "name": "Your own height-sized modules are named", "summary": "A module of your own that sizes itself by the canvas's height (ctx.height / 1080) is listed in the summary, since it may not fit the narrow frame.", "page": "graphics/vertical-graphics", "anchor": "your-own-modules", "where": "File ▸ Make Vertical Version… ▸ summary"}
101	{"id": "graphics-animate-with-an-action", "name": "Animate a graphic's properties", "summary": "Add an action to a graphic clip, select it, and set in the Graphic sub-tab the values the properties should end at, the same way a clip's position or opacity animates.", "page": "graphics/animate-properties", "anchor": "animate-with-an-action", "where": "Clip ▸ Add Action", "keys": "⌥⌘K"}
102	{"id": "graphics-props-that-ramp", "name": "Numbers and colours ramp", "summary": "Across an action a number and a colour property move along the action's curve, colours blending through OKLab.", "page": "graphics/animate-properties", "anchor": "what-ramps", "where": "Clip tab ▸ Graphic ▸ Properties, action selected"}
103	{"id": "graphics-props-that-switch", "name": "Text, checkboxes, menus and pictures switch", "summary": "Across an action a string, boolean, enum or image property holds, then changes to the end's value when the action ends, and its row says \"at end\".", "page": "graphics/animate-properties", "anchor": "what-switches", "where": "Clip tab ▸ Graphic ▸ Properties, action selected"}
104	{"id": "graphics-animate-false", "name": "The animate: false flag", "summary": "Any schema entry may say animate: false so no action ever animates that prop, and it stays the clip's even while an action is selected.", "page": "graphics/animate-properties", "anchor": "stop-a-property-animating", "where": "Clip tab ▸ Graphic ▸ Properties"}
105	{"id": "graphics-animation-range-checks", "name": "Values are checked against the module", "summary": "Each value in an action's end is checked against the module's schema, min and max included, using the module as it is now.", "page": "graphics/animate-properties", "anchor": "values-and-the-module"}
106	{"id": "graphics-animated-start-values", "name": "Where an animated prop starts", "summary": "A property the clip holds no value for starts from the schema's default at the moment an action first names it.", "page": "graphics/animate-properties", "anchor": "where-an-animated-property-starts"}
107	{"id": "graphics-action-badge", "name": "The sub-tab's badge", "summary": "The Graphic sub-tab shows a ◆N badge counting how many properties the selected action animates.", "page": "graphics/animate-properties", "anchor": "the-badge", "where": "Clip tab ▸ Graphic (badge)"}
108	{"id": "graphics-paste-properties", "name": "Paste Graphic Properties", "summary": "Edit ▸ Paste Graphic Properties pastes a copied graphic clip's properties, text and colours included, onto every selected clip drawn by the same module.", "page": "graphics/copy-properties", "anchor": "paste-graphic-properties", "where": "Edit ▸ Paste Graphic Properties (no shortcut)"}
109	{"id": "graphics-paste-attributes-difference", "name": "How it differs from Paste Attributes", "summary": "Edit ▸ Paste Attributes (⌥⌘V) never carries graphic properties.", "page": "graphics/copy-properties", "anchor": "how-it-differs-from-paste-attributes", "where": "Edit ▸ Paste Attributes", "keys": "⌥⌘V"}
110	{"id": "graphics-copy-a-clip", "name": "Copying a graphic clip", "summary": "Copying and pasting a graphic clip pastes a clip that names its module; the module's .js file, fonts and pictures are not copied.", "page": "graphics/copy-properties", "anchor": "copy-a-graphic-clip", "where": "Edit ▸ Copy", "keys": "⌘C"}
111	{"id": "graphics-add-font", "name": "Add Font to Graphics", "summary": "File ▸ Add Font to Graphics… copies a .ttf or .otf file into the project's graphics/fonts/, and every graphic in the project can then use it.", "page": "graphics/fonts-and-pictures", "anchor": "add-a-font", "where": "File ▸ Add Font to Graphics… (no key equivalent)"}
112	{"id": "graphics-exact-family-names", "name": "Exact font family names", "summary": "The family name a module must use is the one the graphics engine reads from the file, which can differ from the name Font Book or other apps show.", "page": "graphics/fonts-and-pictures", "anchor": "use-the-exact-family-name", "where": "Clip tab ▸ Graphic ▸ Source"}
113	{"id": "graphics-bundled-fonts", "name": "Bundled fonts", "summary": "Graphics can draw with seven bundled families on every Mac, with nothing to install.", "page": "graphics/fonts-and-pictures", "anchor": "bundled-fonts"}
114	{"id": "graphics-generic-font-families", "name": "Generic font families", "summary": "serif, sans-serif and monospace draw in bundled faces: Source Serif 4, Source Sans 3 and IBM Plex Mono.", "page": "graphics/fonts-and-pictures", "anchor": "generic-families"}
115	{"id": "graphics-no-system-fonts", "name": "System fonts are never used", "summary": "Graphics draw only with the bundled fonts and the ones you add to the project, never the fonts installed on your Mac, so a project draws the same everywhere.", "page": "graphics/fonts-and-pictures", "anchor": "system-fonts"}
116	{"id": "graphics-add-image", "name": "Add Image to Graphics", "summary": "File ▸ Add Image to Graphics… copies a PNG, JPEG, GIF, WebP, SVG or SVGZ picture into graphics/assets/, where a module can draw it and an asset property's pop-up lists it.", "page": "graphics/fonts-and-pictures", "anchor": "add-a-picture", "where": "File ▸ Add Image to Graphics… (no key equivalent)"}
117	{"id": "graphics-picture-names-made-legal", "name": "Picture names made legal", "summary": "A picture whose name a module can't refer to is added under a legal name, and a notice says which.", "page": "graphics/fonts-and-pictures", "anchor": "picture-names", "where": "File ▸ Add Image to Graphics…"}
118	{"id": "graphics-drop-in-the-folder", "name": "Dropping files in the folder", "summary": "Fonts and pictures may also be put straight into graphics/fonts/ and graphics/assets/ with the Finder or any tool.", "page": "graphics/fonts-and-pictures", "anchor": "drop-files-in-the-folder"}
119	{"id": "graphics-edit-in-any-editor", "name": "Edit in any editor", "summary": "A module is an ordinary file in the project package's graphics/ folder, so you can edit it in any editor or with your own tools.", "page": "graphics/edit-a-module", "anchor": "edit-in-any-editor", "where": "Clip tab ▸ Graphic ▸ Source ▸ Open in Editor"}
120	{"id": "graphics-live-reload", "name": "Live reload", "summary": "Frame Job watches the graphics folder: when a module, font or picture changes, the paused preview redraws and the inspector updates within a moment, with no reimport.", "page": "graphics/edit-a-module", "anchor": "live-reload", "where": "Clip tab ▸ Graphic ▸ Source ▸ Open in Editor"}
121	{"id": "graphics-file-watch-limit", "name": "How many files are watched", "summary": "Frame Job watches the first 16 module, font and picture files one by one, and the folder itself.", "page": "graphics/edit-a-module", "anchor": "how-many-files-are-watched"}
122	{"id": "graphics-diagnostics", "name": "Diagnostics", "summary": "Every problem a module has comes back as {level, message, line, column, frame}.", "page": "graphics/edit-a-module", "anchor": "diagnostics", "where": "Help ▸ Graphics Reference"}
123	{"id": "graphics-error-card", "name": "The error card", "summary": "A graphic that fails draws a dark red error card in its own box, in place of the graphic, in the preview and in stills.", "page": "graphics/edit-a-module", "anchor": "the-error-card", "where": "Preview"}
124	{"id": "graphics-kept-versions", "name": "Kept versions", "summary": "Whenever Frame Job sees a module's code replaced while the project is open, it keeps the code that was there: the last 10 versions of each module.", "page": "graphics/edit-a-module", "anchor": "kept-versions", "where": "File ▸ Restore Graphic Version…"}
125	{"id": "graphics-api-files", "name": "API.md and API.d.ts beside your modules", "summary": "Frame Job keeps the reference and its TypeScript definitions in graphics/, for an editor or an agent working in the folder.", "page": "graphics/edit-a-module", "anchor": "apimd-and-apidts", "where": "Project package ▸ graphics/ folder"}
126	{"id": "graphics-rename", "name": "Rename Graphic", "summary": "File ▸ Rename Graphic… renames a module, and every clip drawn by it, on the timeline and inside nests, follows the new name.", "page": "graphics/manage-graphics", "anchor": "rename-graphic", "where": "File ▸ Rename Graphic… (no key equivalent)"}
127	{"id": "graphics-rename-survives-undo", "name": "A rename survives undo", "summary": "Undoing or redoing a rename moves the module's file back into step with its clips.", "page": "graphics/manage-graphics", "anchor": "undo-a-rename", "where": "Edit ▸ Undo"}
128	{"id": "graphics-delete", "name": "Delete Graphic", "summary": "File ▸ Delete Graphic… deletes a module that no clip uses, keeping its code so it can be restored.", "page": "graphics/manage-graphics", "anchor": "delete-graphic", "where": "File ▸ Delete Graphic… (no key equivalent)"}
129	{"id": "graphics-restore-version", "name": "Restore Graphic Version", "summary": "File ▸ Restore Graphic Version… puts back the newest kept version of a module's code, deleted modules included.", "page": "graphics/manage-graphics", "anchor": "restore-graphic-version", "where": "File ▸ Restore Graphic Version… (no key equivalent)"}
130	{"id": "graphics-duplicate-as-new", "name": "Duplicate as New Graphic", "summary": "Duplicate as New Graphic… writes a copy of the module under a new name and switches the selected clips to it, so you can change one clip's look without changing every clip that shares the module.", "page": "graphics/manage-graphics", "anchor": "duplicate-as-new-graphic", "where": "Clip tab ▸ Graphic ▸ Source ▸ Duplicate as New Graphic…"}
131	{"id": "graphics-file-sheets", "name": "The sheets and their refusals", "summary": "Rename, Delete and Restore each open a small sheet with a Graphic: pop-up of the project's modules, which closes without a message on success and stays open on a refusal.", "page": "graphics/manage-graphics", "anchor": "when-frame-job-wont-do-it", "where": "File ▸ Rename Graphic…, Delete Graphic…, Restore Graphic Version… ▸ Graphic:"}
132	{"id": "graphics-as-a-matte", "name": "Show video inside a graphic", "summary": "A graphic can't read a video's pixels, but it can shape one: put the graphic on the track directly above the video and set that track to a matte, and the video shows only where the graphic draws or, inverted, where it doesn't.", "page": "graphics/video-inside-a-graphic", "anchor": "show-video-inside-a-graphic", "where": "Track ▸ Matte"}
133	{"id": "graphics-draw-ahead", "name": "Drawing ahead while playing", "summary": "While a preview plays forward over a graphic, Frame Job draws upcoming frames on spare processor cores ahead of the playhead, so heavy graphics play smoothly.", "page": "graphics/playback-and-memory", "anchor": "drawing-ahead-while-playing", "where": "Automatic"}
134	{"id": "graphics-kept-frames", "name": "Kept frames", "summary": "A window keeps the graphic frames it has drawn in memory while it is open, so a stretch you play again comes from memory.", "page": "graphics/playback-and-memory", "anchor": "kept-frames", "where": "Automatic"}
135	{"id": "graphics-memory-budget", "name": "The memory budget", "summary": "The drawn frames held ahead and kept share one budget of at most a quarter of your Mac's memory, and less when memory is short.", "page": "graphics/playback-and-memory", "anchor": "the-memory-budget", "where": "Automatic"}
136	{"id": "graphics-repeat-frames", "name": "Repeat frames skip the draw", "summary": "A frame whose SVG is unchanged, such as a hold or a static graphic, reuses the last picture.", "page": "graphics/playback-and-memory", "anchor": "repeat-frames", "where": "Automatic"}
137	{"id": "graphics-picture-cache", "name": "The picture cache", "summary": "PNG and JPEG pictures a graphic draws are decoded once and cached, so image-heavy graphics draw faster.", "page": "graphics/playback-and-memory", "anchor": "the-picture-cache", "where": "Automatic"}
138	{"id": "graphics-background-render", "name": "Background render", "summary": "When you leave Frame Job alone, the window you last used draws its graphics ahead of the paused playhead, so the next play is smooth from the start.", "page": "graphics/playback-and-memory", "anchor": "background-render", "where": "Frame Job ▸ Settings… ▸ Playback ▸ Background render", "keys": "⌘,"}
139	{"id": "graphics-background-render-delay", "name": "Start after … seconds", "summary": "Start after … seconds sets how long Frame Job must be left alone before Background render starts.", "page": "graphics/playback-and-memory", "anchor": "set-how-long-it-waits", "where": "Frame Job ▸ Settings… ▸ Playback ▸ Start after … seconds", "keys": "⌘,"}
140	{"id": "graphics-background-render-stops", "name": "What stops Background render", "summary": "Any activity in Frame Job stops the pass at once, and it starts again after the same wait.", "page": "graphics/playback-and-memory", "anchor": "what-stops-background-render", "where": "Frame Job ▸ Settings… ▸ Playback"}
141	{"id": "graphics-export-as-asked", "name": "An export draws the graphics as asked", "summary": "An export draws each graphic as its module stood when the export was queued, the same as the preview, whatever you edit next.", "page": "graphics/graphics-in-exports", "anchor": "what-an-export-draws", "where": "File ▸ Export…", "keys": "⌘E"}
142	{"id": "graphics-export-parallel", "name": "Parallel rendering", "summary": "An export draws its graphics ahead on worker threads, one fewer than the Mac's active cores.", "page": "graphics/graphics-in-exports", "anchor": "parallel-rendering", "where": "Automatic"}
143	{"id": "graphics-export-refused", "name": "A broken graphic stops an export starting", "summary": "An export that would draw a graphic whose module is missing or doesn't compile is not started, and the message names each graphic and its first error.", "page": "graphics/graphics-in-exports", "anchor": "when-a-graphic-wont-compile", "where": "File ▸ Export…", "keys": "⌘E"}
144	{"id": "graphics-export-stops", "name": "A graphic failing mid-export", "summary": "A graphic that fails partway through stops the export at that frame, names the graphic, and writes no file.", "page": "graphics/graphics-in-exports", "anchor": "when-a-graphic-fails-partway", "where": "File ▸ Export…"}
145	{"id": "graphics-export-warnings", "name": "Graphic warnings in an export", "summary": "Warnings a graphic gives while drawing don't stop the export, and a finished export reports each distinct one with its name and frame.", "page": "graphics/graphics-in-exports", "anchor": "warnings-in-a-finished-export", "where": "Exporting sheet"}
146	{"id": "graphics-frozen-clock", "name": "The frozen clock", "summary": "Date is frozen in a graphic, so nothing depends on when it is drawn and an export matches the preview.", "page": "graphics/graphics-in-exports", "anchor": "the-frozen-clock", "where": "Help ▸ Graphics Reference"}
147	{"id": "graphics-agent-loop", "name": "The write, render and place loop", "summary": "An agent connected over MCP can do the whole job: read the API, write a module, look at it, add fonts and pictures, place it, change it, animate it and check a frame of the timeline.", "page": "graphics/agents-and-graphics", "anchor": "the-loop"}
148	{"id": "graphics-agent-reference", "name": "Read the API", "summary": "graphic_reference answers the whole graphics API as Markdown, for a model to read once before writing a graphic.", "page": "graphics/agents-and-graphics", "anchor": "read-the-api", "where": "Help ▸ Graphics Reference"}
149	{"id": "graphics-agent-write", "name": "Write a module", "summary": "write_graphic writes graphics/<name>.js and answers the compile of that exact text, so an agent can iterate.", "page": "graphics/agents-and-graphics", "anchor": "write-a-module"}
150	{"id": "graphics-agent-contact-sheet", "name": "A contact sheet", "summary": "render_graphic draws a module without placing a clip: up to 16 frames on a PNG contact sheet, each frame's number under it.", "page": "graphics/agents-and-graphics", "anchor": "a-contact-sheet"}
151	{"id": "graphics-agent-svg", "name": "One frame's SVG", "summary": "render_graphic with format: \"svg\" answers one frame's SVG text, its diagnostics and the ctx it was drawn with.", "page": "graphics/agents-and-graphics", "anchor": "one-frames-svg"}
152	{"id": "graphics-agent-list-and-insert", "name": "List and insert", "summary": "list_graphics lists what the Insert Graphic sheet shows, in its order, and insert_graphic is its Insert.", "page": "graphics/agents-and-graphics", "anchor": "list-and-insert", "where": "Insert ▸ Graphic…"}
153	{"id": "graphics-agent-place", "name": "Place a clip", "summary": "add_graphic_clip places a clip drawn by a module already in graphics/ on a chosen track and time.", "page": "graphics/agents-and-graphics", "anchor": "place-a-clip", "where": "Insert ▸ Graphic…"}
154	{"id": "graphics-agent-set-graphic", "name": "Change a clip", "summary": "set_graphic patches what graphic clips are drawn from: another module, size, length or props.", "page": "graphics/agents-and-graphics", "anchor": "change-a-clip", "where": "Clip tab ▸ Graphic ▸ Properties, Size, Timeline"}
155	{"id": "graphics-agent-get-graphic", "name": "Read a module or the folder", "summary": "get_graphic reads one module, or with no name lists the whole graphics folder.", "page": "graphics/agents-and-graphics", "anchor": "read-a-module-or-the-folder", "where": "Clip tab ▸ Graphic ▸ Source"}
156	{"id": "graphics-agent-file-tools", "name": "Edit the folder with file tools", "summary": "An agent may also edit the graphics folder with its own file tools, and the app sees the change within a moment.", "page": "graphics/agents-and-graphics", "anchor": "file-tools"}
157	{"id": "graphics-agent-undo-rules", "name": "Undo rules", "summary": "File writes in graphics/ are not undo steps and don't mark the project edited, while placing and changing clips are undo steps.", "page": "graphics/agents-and-graphics", "anchor": "undo-rules"}
158	{"id": "graphics-agent-render-frame", "name": "Graphics in render_frame", "summary": "When a graphic in the frame failed or warned, render_frame names it with its frame and diagnostic, and a failed graphic draws its error card in the picture.", "page": "graphics/agents-and-graphics", "anchor": "graphics-in-render-frame"}
159	{"id": "graphics-assistant", "name": "The Assistant and graphics", "summary": "The Assistant tab can write, change, place, render, rename, delete, restore, export and import graphics.", "page": "graphics/agents-and-graphics", "anchor": "the-assistant", "where": "Inspector ▸ Assistant", "needs": "your Anthropic key"}
160	{"id": "graphics-module-shape", "name": "The shape of a module", "summary": "A graphic is one JavaScript ES module exporting render, with optional meta and schema, and render returns an SVG string for each frame.", "page": "graphics/write-a-module", "anchor": "the-module", "where": "Help ▸ Graphics Reference"}
161	{"id": "graphics-module-meta", "name": "meta", "summary": "A module's meta names it, sets a new clip's default length and size, and files it in the Insert Graphic sheet.", "page": "graphics/write-a-module", "anchor": "meta", "where": "Help ▸ Graphics Reference"}
162	{"id": "graphics-module-ctx", "name": "ctx", "summary": "render receives ctx with the project's rate, the time, the clip's length and progress, and the sizes.", "page": "graphics/write-a-module", "anchor": "ctx", "where": "Help ▸ Graphics Reference"}
163	{"id": "graphics-resolution-independent", "name": "Resolution-independent drawing", "summary": "Writing every coordinate against ctx.width and ctx.height lets one graphic draw at any size or shape.", "page": "graphics/write-a-module", "anchor": "resolution-independent-drawing", "where": "Help ▸ Graphics Reference"}
164	{"id": "graphics-module-schema", "name": "The schema", "summary": "A module's schema declares its properties, which become inspector controls and the props render receives.", "page": "graphics/write-a-module", "anchor": "the-schema", "where": "Help ▸ Graphics Reference"}
165	{"id": "graphics-prop-types", "name": "Prop types", "summary": "A schema entry's type is string, number, boolean, color, enum or asset.", "page": "graphics/write-a-module", "anchor": "prop-types", "where": "Help ▸ Graphics Reference"}
166	{"id": "graphics-tolerant-props", "name": "Tolerant props", "summary": "props always has every schema key, and a stored value that does not fit is a warning, not a failure: the default is drawn and the frame still draws.", "page": "graphics/write-a-module", "anchor": "tolerant-props", "where": "Help ▸ Graphics Reference"}
167	{"id": "graphics-svg-engine", "name": "The SVG the engine draws", "summary": "render's SVG is rasterized by resvg, with text, PNG, JPEG, GIF, WebP and SVG images, and compressed SVGZ.", "page": "graphics/write-a-module", "anchor": "the-svg-the-engine-draws"}
168	{"id": "graphics-sandbox", "name": "The sandbox", "summary": "A graphic runs in a sandbox with no import, eval, Function, Math.random, fetch, files, clock, performance, WebAssembly or Intl.", "page": "graphics/write-a-module", "anchor": "the-sandbox", "where": "Help ▸ Graphics Reference"}
169	{"id": "graphics-modern-javascript", "name": "Modern JavaScript", "summary": "Modern syntax works in a module.", "page": "graphics/write-a-module", "anchor": "modern-javascript", "where": "Help ▸ Graphics Reference"}
170	{"id": "graphics-time-budget", "name": "The time budget", "summary": "Each frame has 250 ms to draw in the preview and 2 s in an export, so a runaway graphic reports an error instead of hanging.", "page": "graphics/write-a-module", "anchor": "the-time-budget", "where": "Help ▸ Graphics Reference"}
171	{"id": "graphics-size-limits", "name": "Size and memory limits", "summary": "An engine has 64 MB of heap and 1 MB of stack, a graphic draws at most 8192 pixels on a side, and render must return an SVG string of at most 8 MiB.", "page": "graphics/write-a-module", "anchor": "limits", "where": "Help ▸ Graphics Reference"}
172	{"id": "graphics-reference", "name": "The graphics reference", "summary": "Help ▸ Graphics Reference opens the whole graphics API reference in your default Markdown app, with or without a project open.", "page": "graphics/module-api", "anchor": "the-graphics-reference", "where": "Help ▸ Graphics Reference"}
173	{"id": "graphics-api-svg", "name": "svg()", "summary": "svg(ctx, body, {background}) writes the root element with the right size and viewBox.", "page": "graphics/module-api", "anchor": "svg", "where": "Help ▸ Graphics Reference"}
174	{"id": "graphics-api-interpolate", "name": "interpolate()", "summary": "interpolate maps a value through matching input and output ranges.", "page": "graphics/module-api", "anchor": "interpolate", "where": "Help ▸ Graphics Reference"}
175	{"id": "graphics-api-easing", "name": "Easing", "summary": "Easing gives ready-made curves for interpolate.", "page": "graphics/module-api", "anchor": "easing", "where": "Help ▸ Graphics Reference"}
176	{"id": "graphics-api-spring", "name": "spring()", "summary": "spring gives a physical spring from one value to another.", "page": "graphics/module-api", "anchor": "spring", "where": "Help ▸ Graphics Reference"}
177	{"id": "graphics-api-interpolate-colors", "name": "interpolateColors()", "summary": "interpolateColors blends colours in OKLab.", "page": "graphics/module-api", "anchor": "interpolatecolors", "where": "Help ▸ Graphics Reference"}
178	{"id": "graphics-api-random", "name": "random()", "summary": "random(seed) answers a repeatable number in [0, 1) from a number or string seed.", "page": "graphics/module-api", "anchor": "random", "where": "Help ▸ Graphics Reference"}
179	{"id": "graphics-api-noise", "name": "noise2D() and noise3D()", "summary": "Simplex noise for organic motion.", "page": "graphics/module-api", "anchor": "noise", "where": "Help ▸ Graphics Reference"}
