import json
import os
import re

root = "/Users/kevingalligan/devel/framejob/.claude/worktrees/help-docs"
base = "/private/tmp/claude-501/-Users-kevingalligan-devel-framejob/9cfd7405-83ec-4caa-905f-7b97a20f2cc9/scratchpad"
raw = json.load(open(base + "/work/gfx_fixes_raw.json", encoding="utf-8"))
d = json.load(open(root + "/docs/site/src/data/features.json", encoding="utf-8"))
rows = {f["id"]: f for f in [s for s in d["sections"] if s["id"] == "graphics"][0]["features"]}

out = []
for u in raw["updates"]:
    row = rows[u["id"]]  # KeyError on a bad id
    kept = {"id": u["id"]}
    for k, v in u.items():
        if k != "id" and row.get(k, "") != v:
            kept[k] = v
    if len(kept) > 1:
        out.append(kept)
    else:
        print("NO-OP", u["id"])

ids = [u["id"] for u in out]
assert len(ids) == len(set(ids)), "duplicate id"

merged = {i: dict(r) for i, r in rows.items()}
for u in out:
    merged[u["id"]].update(u)

banned = re.compile(
    r"\b(refus\w*|the op|the core|answers?|ticks?|patch\w*|powerful|seamless|effortless|robust|simply|just|easily|schema's|engine reads|stem)\b",
    re.I,
)
for i, r in merged.items():
    s = r["summary"]
    if len(s) > 140:
        print("LONG", len(s), i, s)
    for field in ("name", "summary", "where"):
        m = banned.search(r.get(field, ""))
        if m:
            print("WORD", m.group(0), i, field, r.get(field))
    if re.search(r"\(no |no key equivalent|no shortcut|Automatic", r.get("where", "")):
        print("WHERE", i, r["where"])

names = {}
for i, r in merged.items():
    names.setdefault(r["name"], []).append(i)
for n, v in names.items():
    if len(v) > 1:
        print("SAME NAME", n, v)

dest = base + "/inventory/feature-fixes/graphics.json"
os.makedirs(os.path.dirname(dest), exist_ok=True)
with open(dest, "w", encoding="utf-8") as fh:
    json.dump({"updates": out, "remove": raw["remove"]}, fh, ensure_ascii=False, indent=1)
    fh.write("\n")
print("rows", len(rows), "updates", len(out), "remove", len(raw["remove"]))

